--
-- Name: generate_audit_integrity_hash(); Type: FUNCTION; Schema: public; Owner: usa_notray_user
--

CREATE FUNCTION public.generate_audit_integrity_hash() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Generate a simple integrity hash based on key fields
    NEW.audit_log_integrity_hash := encode(
        digest(
            COALESCE(NEW.session_id::text, '') || '-' ||
            COALESCE(NEW.user_id::text, '') || '-' ||
            COALESCE(NEW.event_type, '') || '-' ||
            COALESCE(extract(epoch from NEW.timestamp)::text, ''),
            'sha256'
        ),
        'hex'
    );
    
    -- Set updated_at timestamp
    NEW.updated_at := NOW();
    
    RETURN NEW;
END;
$$;


