--
-- Name: audit_trail_detailed; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.audit_trail_detailed AS
 SELECT at.id,
    at.session_id,
    at.user_id,
    at.action,
    at.details,
    at.document_id,
    at.page_number,
    at."timestamp",
    at.user_role,
    at.ip_address,
    at.device_fingerprint,
    at.event_type,
    at.event_details,
    at.coordinates_page_reference,
    at.previous_state,
    at.new_state,
    at.authentication_method,
    at.verification_result,
    at.credential_reference,
    at.seal_applied,
    at.notary_certificate_reference,
    at.digital_signature_hash,
    at.system_source,
    at.audit_log_integrity_hash,
    at.retention_metadata,
    at.created_at,
    at.updated_at,
    ((u.first_name || ' '::text) || u.last_name) AS user_full_name,
    u.email AS user_email,
    jd.original_name AS document_name,
    es.session_type,
    j.id AS job_id,
    j.title_company,
    j.closing_type
   FROM ((((public.audit_trail at
     LEFT JOIN public.users u ON ((at.user_id = u.id)))
     LEFT JOIN public.job_documents jd ON ((at.document_id = jd.id)))
     LEFT JOIN public.editor_sessions es ON ((at.session_id = es.id)))
     LEFT JOIN public.jobs j ON ((es.job_id = j.id)));


ALTER VIEW public.audit_trail_detailed OWNER TO postgres;

