--
-- Name: participant_role_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.participant_role_summary AS
 SELECT jp.id,
    jp.job_id,
    jp.user_id,
    jp.email,
    u.username,
    u.first_name,
    u.last_name,
    jp.primary_role AS user_system_role,
    jp.job_specific_role AS job_role,
    jp.requires_id_verification,
    jp.id_verification_completed,
    jp.invite_status,
        CASE
            WHEN (jp.primary_role <> jp.job_specific_role) THEN true
            ELSE false
        END AS has_dual_role,
        CASE
            WHEN (jp.requires_id_verification AND (NOT jp.id_verification_completed)) THEN 'verification_required'::text
            WHEN (jp.requires_id_verification AND jp.id_verification_completed) THEN 'verified'::text
            ELSE 'no_verification_needed'::text
        END AS verification_status
   FROM (public.job_participants jp
     LEFT JOIN public.users u ON ((jp.user_id = u.id)));


ALTER VIEW public.participant_role_summary OWNER TO postgres;

--
-- Name: VIEW participant_role_summary; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON VIEW public.participant_role_summary IS 'Summary view of participant roles and verification status for easy querying';


